const APP_VERSION='1.14.2';
const euro=new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'});
const dateLabel=new Intl.DateTimeFormat('de-DE',{day:'2-digit',month:'short',year:'numeric'});
const today=()=>new Date().toISOString().slice(0,10);
const formatCentsInput=value=>{const digits=String(value).replace(/\D/g,'');return digits?(Number(digits)/100).toLocaleString('de-DE',{minimumFractionDigits:2,maximumFractionDigits:2}):''};
const parseAmountInput=value=>Number(String(value).replace(/\./g,'').replace(',','.'));
const displayAmountInput=value=>Number(value).toLocaleString('de-DE',{minimumFractionDigits:2,maximumFractionDigits:2});
const createId=()=>globalThis.crypto?.randomUUID?.()||`${Date.now().toString(36)}-${Math.random().toString(36).slice(2,10)}`;
const q=s=>document.querySelector(s),qa=s=>document.querySelectorAll(s);
const initial={accounts:[{id:'save',name:'Sparen',icon:'↗',color:'#0d5bd7',target:500},{id:'living',name:'Lebenshaltung',icon:'🛒',color:'#13a2b8',target:930},{id:'fixed',name:'Gemeinkosten',icon:'⌂',color:'#6a69d8',target:1000},{id:'clothes',name:'Kleidung',icon:'♧',color:'#e4854d',target:100}],categories:[{id:'shopping',name:'Einkaufen',icon:'🛒',color:'#13a2b8'},{id:'tobacco',name:'Tabak',icon:'🚬',color:'#a66f47'},{id:'cats',name:'Katzen',icon:'🐈',color:'#d88b50'},{id:'groceries',name:'Lebensmittel',icon:'🥕',color:'#38a169'},{id:'rent',name:'Miete',icon:'⌂',color:'#6a69d8'},{id:'electricity',name:'Strom',icon:'ϟ',color:'#edb62c'},{id:'phone',name:'Telefon',icon:'◉',color:'#0d5bd7'},{id:'clothes',name:'Kleidung',icon:'♧',color:'#e4854d'},{id:'invest',name:'Aktienportfolio',icon:'↗',color:'#149876'}],transactions:[],recurring:[{id:'rent-1',name:'Miete',amount:750,day:3,category:'rent'},{id:'phone-1',name:'Telefon',amount:24.99,day:8,category:'phone'},{id:'chatgpt-1',name:'ChatGPT',amount:23,day:15,category:'phone'}],recurringIncome:[],shortcuts:[{id:'shopping',name:'Einkaufen',icon:'🛒',account:'living',category:'shopping'},{id:'tobacco',name:'Tabak',icon:'🚬',account:'living',category:'tobacco'},{id:'cats',name:'Katzen',icon:'🐈',account:'living',category:'cats'}],goals:[],budgetHistory:[]};
const storedBudgetData=localStorage.getItem('mein-budget-data');let state=JSON.parse(storedBudgetData||'null')||structuredClone(initial);const isFirstLaunch=!storedBudgetData;if(isFirstLaunch){state.tutorialInviteEligible=true;state.recurring=[]}
let editingShortcutId=null,editingRecurringId=null,editingAccountId=null,editingGoalId=null,editingRecurringIncomeId=null,editingTransactionId=null,editingPaymentAccountId=null,pendingLeftover=null;
let installEvent=null;
for(const key of ['accounts','categories','transactions','recurring','recurringIncome','shortcuts','goals','budgetHistory'])if(!state[key])state[key]=structuredClone(initial[key]);
initial.categories.forEach(c=>{if(!state.categories.some(x=>x.id===c.id))state.categories.push(c)});
if(state.dailyCarryover===undefined)state.dailyCarryover=0;if(!state.budgetCycleStart)state.budgetCycleStart=today();if(state.budgetCycleInitialized===undefined)state.budgetCycleInitialized=false;
const defaultTags=['Kleidung','Software','Elektronik','Haushalt','Lebensmittel','Katzen','Gesundheit','Mobilität','Abos','Unterhaltung','Reisen','Bildung','Geschenke','Arbeit'];
if(!state.tags)state.tags=defaultTags;
if(!state.paymentAccounts)state.paymentAccounts=[{id:'main',name:'Hauptkonto',icon:'▣'}];
state.transactions.forEach(t=>{if(!t.paymentAccount)t.paymentAccount='main'});
state.transactions.forEach(t=>{if(t.category==='cats')t.account='living'});
const save=()=>localStorage.setItem('mein-budget-data',JSON.stringify(state));
const account=id=>state.accounts.find(x=>x.id===id)||{name:'Unbekannt',icon:'?' ,color:'#71829b',target:0};
const paymentAccount=id=>state.paymentAccounts.find(x=>x.id===id)||{name:'Hauptkonto',icon:'▣'};
const category=id=>state.categories.find(x=>x.id===id)||{name:'Sonstiges',icon:'•',color:'#71829b'};
const accountBalance=id=>state.transactions.filter(t=>t.account===id).reduce((sum,t)=>sum+(t.type==='expense'?-Number(t.amount):Number(t.amount)),0);
const iconStyle=x=>`style="--icon:${x.color};--icon-bg:${x.color}1c"`;
const monthMarker=()=>today().slice(0,7);
const monthTransactions=()=>state.transactions.filter(t=>t.date.startsWith(monthMarker()));
const newestFirst=entries=>entries.map((t,index)=>({t,index})).sort((a,b)=>b.t.date.localeCompare(a.t.date)||b.index-a.index).map(x=>x.t);
function toast(text){const el=q('#toast');el.textContent=text;el.style.transform='translate(-50%,0)';setTimeout(()=>el.style.transform='translate(-50%,120px)',2800)}
function renderAccounts(){const html=state.accounts.map(a=>{const balance=accountBalance(a.id),pct=Math.max(0,Math.min(100,a.target?balance/a.target*100:0));return `<article class="account" style="--icon:${a.color};--icon-bg:${a.color}1c"><div class="account-top"><span class="account-icon">${a.icon}</span><button class="delete" data-edit-account="${a.id}" title="Konto bearbeiten">⋯</button></div><div class="account-value">${euro.format(balance)}</div><div class="account-label">${a.name}</div><div class="progress"><span style="width:${pct}%"></span></div><div class="progress-label"><span>${Math.round(pct)}% gefüllt</span><span>${a.target?`Ziel ${euro.format(a.target)}`:'Ohne Ziel'}</span></div></article>`}).join('');q('#accountGrid').innerHTML=html;q('#slideAccounts').innerHTML=html}
function transactionHtml(t,controls=true){const c=category(t.category),tags=(t.tags||[]).map(tag=>`<span class="tag">${tag}</span>`).join('');return `<div class="transaction"><div class="transaction-icon" ${iconStyle(c)}>${c.icon}</div><div><div class="transaction-name">${t.name}${t.receipt?` <button class="receipt-link" data-receipt="${t.id}" title="Beleg ansehen">⌑</button>`:''}</div><div class="transaction-sub">${account(t.account).name} · ${paymentAccount(t.paymentAccount).icon} ${paymentAccount(t.paymentAccount).name} · ${dateLabel.format(new Date(t.date+'T12:00:00'))}${t.note?' · '+t.note:''}</div>${tags?`<div class="tag-row">${tags}</div>`:''}</div><div class="transaction-amount ${t.type==='expense'?'negative':'positive'}">${t.type==='expense'?'−':'+'} ${euro.format(t.amount)}</div>${controls?`<span><button class="delete" data-open-edit-transaction="${t.id}" title="Buchung bearbeiten">⋯</button><button class="delete" data-delete-transaction="${t.id}" title="Buchung löschen">×</button></span>`:''}</div>`}
function renderTransactions(){const all=newestFirst(state.transactions),search=q('#filterSearch').value.trim().toLowerCase(),acc=q('#filterAccount').value,payment=q('#filterPaymentAccount').value,cat=q('#filterCategory').value,tag=q('#filterTag').value,type=q('#filterType').value,from=q('#filterFrom').value,to=q('#filterTo').value;const filtered=all.filter(t=>(acc==='all'||t.account===acc)&&(payment==='all'||t.paymentAccount===payment)&&(cat==='all'||t.category===cat)&&(tag==='all'||(t.tags||[]).includes(tag))&&(type==='all'||t.type===type)&&(!from||t.date>=from)&&(!to||t.date<=to)&&(!search||`${t.name} ${t.note||''} ${(t.tags||[]).join(' ')}`.toLowerCase().includes(search)));const recentHtml=all.slice(0,5).map(t=>transactionHtml(t,false)).join('')||'<p class="view-intro">Noch keine Bewegungen. Füge dein erstes Gehalt hinzu.</p>';q('#recentTransactions').innerHTML=recentHtml;q('#slideTransactions').innerHTML=all.slice(0,10).map(t=>transactionHtml(t,false)).join('')||'<p class="view-intro">Noch keine Bewegungen. Füge dein erstes Gehalt hinzu.</p>';q('#transactionTable').innerHTML=filtered.map(t=>transactionHtml(t)).join('')||'<p class="view-intro">Für diese Filter gibt es keine Buchungen.</p>'}
function renderChart(){const groups={};monthTransactions().filter(t=>t.type==='expense').forEach(t=>groups[t.category]=(groups[t.category]||0)+Number(t.amount));const max=Math.max(...Object.values(groups),1),total=Object.values(groups).reduce((s,x)=>s+x,0);const html=Object.entries(groups).sort((a,b)=>b[1]-a[1]).map(([id,value])=>{const c=category(id);return `<div class="chart-row"><span>${c.icon}</span><div><div class="transaction-sub">${c.name}</div><div class="chart-bar"><span style="width:${value/max*100}%;--chart:${c.color}"></span></div></div><span class="chart-value">${euro.format(value)}</span></div>`}).join('')||'<p class="view-intro">Noch keine Ausgaben in diesem Monat.</p>';q('#categoryChart').innerHTML=html;q('#slideCategories').innerHTML=html;q('#spentThisMonth').textContent=euro.format(total)}
function tagColor(tag){let h=0;for(let i=0;i<tag.length;i++)h=(h*31+tag.charCodeAt(i))>>>0;return `hsl(${h%360} 60% 45%)`}
function renderTagChart(){const groups={};monthTransactions().filter(t=>t.type==='expense').forEach(t=>(t.tags||[]).forEach(tag=>groups[tag]=(groups[tag]||0)+Number(t.amount)));const max=Math.max(...Object.values(groups),1);q('#slideTags').innerHTML=Object.entries(groups).sort((a,b)=>b[1]-a[1]).map(([tag,value])=>{const c=tagColor(tag);return `<div class="chart-row"><span class="tag-chart-dot" style="background:${c}"></span><div><div class="transaction-sub">#${tag}</div><div class="chart-bar"><span style="width:${value/max*100}%;--chart:${c}"></span></div></div><span class="chart-value">${euro.format(value)}</span></div>`}).join('')||'<p class="view-intro">Noch keine getaggten Ausgaben in diesem Monat.</p>'}
function renderTrendChart(){const now=new Date(),daysInMonth=now.getDate(),totals=Array.from({length:daysInMonth},()=>0);monthTransactions().filter(t=>t.type==='expense').forEach(t=>{const day=Number(t.date.slice(8,10));if(day>=1&&day<=daysInMonth)totals[day-1]+=Number(t.amount)});const max=Math.max(...totals,1),total=totals.reduce((s,x)=>s+x,0);const bars=totals.map((v,i)=>{const day=i+1;return `<span class="trend-bar${day===now.getDate()?' today':''}" style="height:${v?Math.max(6,v/max*100):2}%" title="${day}.: ${euro.format(v)}"></span>`}).join('');q('#slideTrend').innerHTML=`<div class="trend-bars">${bars}</div><div class="trend-caption"><span>1.</span><span>${daysInMonth}.</span></div><p class="trend-total">${euro.format(total)} Ausgaben in diesem Monat</p>`}
function renderRecurring(){const marker=monthMarker();q('#recurringList').innerHTML=state.recurring.map(r=>{const c=category(r.category),booked=r.lastBookedMonth===marker;return `<article class="recurring-item"><span class="category-icon" ${iconStyle(c)}>${c.icon}</span><div class="item-main"><div class="item-name">${r.name}</div><div class="item-detail">Fällig am ${r.day}. jeden Monat · ${c.name}${booked?' · diesen Monat gebucht':''}</div></div><div class="item-amount">${euro.format(r.amount)}</div><button class="delete" data-edit-recurring="${r.id}" aria-label="${r.name} bearbeiten">⋯</button><button class="delete" data-delete-recurring="${r.id}" aria-label="${r.name} löschen">×</button></article>`}).join('')||'<p class="view-intro">Noch keine Fixkosten angelegt.</p>';q('#recurringIncomeList').innerHTML=state.recurringIncome.map(r=>{const booked=r.lastBookedMonth===marker;return `<article class="recurring-item"><span class="category-icon" style="--icon:#247a66;--icon-bg:#e6f6f1">↗</span><div class="item-main"><div class="item-name">${r.name}</div><div class="item-detail">Fällig am ${r.day}. jeden Monat · auf ${account(r.account).name}${booked?' · diesen Monat gebucht':''}</div></div><div class="item-amount positive">${euro.format(r.amount)}</div><button class="delete" data-edit-recurring-income="${r.id}" aria-label="${r.name} bearbeiten">⋯</button><button class="delete" data-delete-recurring-income="${r.id}" aria-label="${r.name} löschen">×</button></article>`}).join('')||'<p class="view-intro">Noch keine regelmäßigen Einnahmen angelegt.</p>'}
function renderCategories(){q('#categoryList').innerHTML=state.categories.map(c=>`<article class="category-item" ${iconStyle(c)}><span class="category-icon">${c.icon}</span><div class="item-main"><div class="item-name">${c.name}</div></div><button class="delete" data-edit-category="${c.id}">⋯</button><button class="delete" data-delete-category="${c.id}">×</button></article>`).join('')}
function renderTagPicker(tags=[...new Set([...state.tags,...state.transactions.flatMap(t=>t.tags||[])])].sort()){const selected=q('#transactionTags').value.split(',').map(t=>t.trim()).filter(Boolean);q('#transactionTagsLabel').textContent=selected.length?selected.join(', '):'Auswählen';q('#tagPickerOptions').innerHTML=tags.map(tag=>`<label><input type="checkbox" value="${tag}" ${selected.includes(tag)?'checked':''} />${tag}</label>`).join('')}
function options(){const accounts=state.accounts.map(x=>`<option value="${x.id}">${x.name}</option>`).join(''),payments=state.paymentAccounts.map(x=>`<option value="${x.id}">${x.icon} ${x.name}</option>`).join(''),categories=state.categories.map(x=>`<option value="${x.id}">${x.icon} ${x.name}</option>`).join(''),tags=[...new Set([...state.tags,...state.transactions.flatMap(t=>t.tags||[])])].sort();for(const id of ['transactionAccount','shortcutAccount','recurringIncomeAccount'])q('#'+id).innerHTML=accounts;for(const id of ['transactionPaymentAccount','recurringPaymentAccount'])q('#'+id).innerHTML=payments;for(const id of ['transactionCategory','recurringCategory','shortcutCategory'])q('#'+id).innerHTML=categories;q('#filterAccount').innerHTML='<option value="all">Alle Budgettöpfe</option>'+accounts;q('#filterPaymentAccount').innerHTML='<option value="all">Alle Zahlkonten</option>'+payments;q('#filterCategory').innerHTML='<option value="all">Alle Kategorien</option>'+categories;q('#filterTag').innerHTML='<option value="all">Alle Tags</option>'+tags.map(t=>`<option value="${t}">${t}</option>`).join('');renderTagPicker(tags)}
function renderSettings(){q('#allocationSettings').innerHTML=state.accounts.map(a=>`<div class="allocation-row"><span>${a.icon} ${a.name}</span><label><input type="number" min="0" step="1" value="${a.target}" data-target="${a.id}" /> <small>€</small></label></div>`).join('')+`<div class="allocation-row daily-budget-setting"><span>☀ Tagesbudget</span><label><input type="number" min="1" step="1" value="${Number(state.dailyBudget)||30}" data-daily-budget /> <small>€ / Tag</small></label></div>`;q('#accountSettings').innerHTML=state.accounts.map(a=>`<div class="shortcut-item"><span class="shortcut-icon">${a.icon}</span><div class="item-main"><div class="item-name">${a.name}</div><div class="item-detail">Budgetziel: ${euro.format(a.target)}</div></div><button class="delete" data-edit-account="${a.id}">⋯</button>${['save','living','fixed','clothes'].includes(a.id)?'':`<button class="delete" data-delete-account="${a.id}">×</button>`}</div>`).join('');q('#paymentAccountSettings').innerHTML=state.paymentAccounts.map(a=>`<div class="shortcut-item"><span class="shortcut-icon">${a.icon}</span><div class="item-main"><div class="item-name">${a.name}</div><div class="item-detail">Zahlkonto für Ausgaben</div></div><button class="delete" data-edit-payment-account="${a.id}">⋯</button>${a.id==='main'?'':`<button class="delete" data-delete-payment-account="${a.id}">×</button>`}</div>`).join('');renderGoals('goalSettings')}
function renderShortcuts(){q('#shortcutList').innerHTML=state.shortcuts.map(s=>`<div class="shortcut-item"><span class="shortcut-icon">${s.icon}</span><div class="item-main"><div class="item-name">${s.name}</div><div class="item-detail">${account(s.account).name} · ${category(s.category).name}</div></div><button class="delete" data-edit-shortcut="${s.id}">⋯</button><button class="delete" data-delete-shortcut="${s.id}">×</button></div>`).join('')||'<p class="view-intro">Noch keine Shortcuts angelegt.</p>'}
function renderFabActions(){const view=document.body.dataset.activeView||'dashboard',sets={transactions:[['income','↗','Einnahme hinzufügen'],['expense','−','Ausgabe hinzufügen']],recurring:[['recurring','↻','Fixkosten anlegen'],['recurringIncome','↗','Regelmäßige Einnahme']],categories:[['category','◇','Kategorie anlegen']],settings:[['account','▣','Budgettopf anlegen'],['paymentAccount','◉','Zahlkonto anlegen'],['goal','◎','Sparziel anlegen'],['shortcut','⚡','Shortcut anlegen']]},actions=sets[view];fabButton.setAttribute('aria-label',view==='dashboard'?'Ausgabe hinzufügen':'Hinzufügen');q('#fabActions').innerHTML=actions?actions.map(([action,icon,label])=>`<button type="button" data-fab-action="${action}"><span class="fab-action-icon">${icon}</span>${label}</button>`).join(''):state.shortcuts.map(s=>`<button type="button" data-dashboard-shortcut="${s.id}"><span class="fab-action-icon">${s.icon}</span>${s.name}</button>`).join('')+'<button type="button" data-fab-generic><span class="fab-action-icon">＋</span>Andere Ausgabe</button>'}
function renderShortcutButtons(){q('#shortcutButtons').innerHTML=state.shortcuts.map(s=>`<button type="button" data-shortcut="${s.id}">${s.icon} ${s.name}</button>`).join('');q('#dashboardShortcuts').innerHTML=state.shortcuts.map(s=>`<button type="button" data-dashboard-shortcut="${s.id}">${s.icon} ${s.name}</button>`).join('')||'<p class="view-intro">Lege unter Einstellungen eigene Shortcuts an.</p>';renderFabActions()}
function goalHtml(g){const pct=Math.max(0,Math.min(100,Number(g.current)/Number(g.target)*100));return `<div class="goal-item"><span>${g.icon}</span><div class="item-main"><div class="item-name">${g.name}</div><div class="progress"><span style="width:${pct}%;--icon:#247a66"></span></div><div class="item-detail">${euro.format(g.current)} von ${euro.format(g.target)}</div></div><button class="delete" data-edit-goal="${g.id}">⋯</button><button class="delete" data-delete-goal="${g.id}">×</button></div>`}
function renderGoals(target){q('#'+target).innerHTML=state.goals.map(goalHtml).join('')||'<p class="view-intro">Lege dein erstes Sparziel an.</p>'}
function cycleDays(until=today()){return Math.max(1,Math.floor((new Date(until+'T12:00:00')-new Date(state.budgetCycleStart+'T12:00:00'))/86400000)+1)}
function cycleSpent(until){return state.transactions.filter(t=>t.type==='expense'&&t.account==='living'&&t.date>=state.budgetCycleStart&&t.date<until).reduce((s,t)=>s+Number(t.amount),0)}
function dailyNumbers(){const tomorrow=new Date();tomorrow.setDate(tomorrow.getDate()+1);const days=cycleDays(),daily=Number(state.dailyBudget)||30,allowance=days*daily+Number(state.dailyCarryover),spent=cycleSpent(tomorrow.toISOString().slice(0,10));return {days,daily,allowance,spent,available:allowance-spent}}
function renderHeader(){const balance=accountBalance('living'),target=account('living').target,pct=target?Math.max(0,Math.min(100,balance/target*100)):0;q('#totalBalance').textContent=euro.format(balance);q('#heroProgressBar').style.width=pct+'%';q('#heroProgress').classList.toggle('low',pct<20);const date=new Intl.DateTimeFormat('de-DE',{weekday:'long',day:'numeric',month:'long'}).format(new Date());q('#todayLabel').textContent=date;q('#topbarDate').textContent=date;q('#transactionDateLabel').textContent=date;q('#recurringDateLabel').textContent=date}
function renderDailyBudget(){const n=dailyNumbers(),days=Math.abs(n.available/n.daily),box=q('#dailyBudget');box.classList.toggle('over',n.available<0);q('#dailyBudgetAmount').textContent=euro.format(n.available);q('#dailyBudgetDays').textContent=(n.available>=0?'noch ':'über ')+days.toLocaleString('de-DE',{maximumFractionDigits:1})+' Tage';
// Die Rechnung dahinter steht nur noch im Tooltip – der Header bleibt ruhig.
box.title=`Seit ${dateLabel.format(new Date(state.budgetCycleStart+'T12:00:00'))}: ${n.days} ${n.days===1?'Tag':'Tage'} × ${euro.format(n.daily)}${state.dailyCarryover?` + Übertrag ${euro.format(state.dailyCarryover)}`:''} = ${euro.format(n.allowance)} · ausgegeben: ${euro.format(n.spent)}`}
function renderWarnings(){const warnings=[];const living=accountBalance('living'),target=account('living').target;if(living>=0&&target&&living/target<.2)warnings.push(`Lebenshaltungskonto ist zu über 80 % verbraucht.`);q('#budgetWarnings').innerHTML=warnings.map(w=>`<div class="warning">⚑ ${w}</div>`).join('')}
function renderBackupReminder(){const last=state.lastBackupDate?new Date(state.lastBackupDate+'T12:00:00'):null,days=last?Math.floor((new Date()-last)/86400000):99,due=days>=14;q('#heroAlert').hidden=!due;if(due)q('#backupReminder').innerHTML=`<strong>Backup-Erinnerung</strong><small>${last?`Dein letztes Backup ist ${days} Tage alt.`:'Du hast noch kein Backup gespeichert.'}</small><div class="hero-alert-actions"><button class="text-button" data-load-backup>Backup laden</button><button class="secondary-button" id="quickBackup">Backup speichern</button></div>`;closeBackupReminder()}
function renderSummary(){const n=dailyNumbers(),income=state.transactions.filter(t=>t.type==='income'&&t.date>=state.budgetCycleStart).reduce((s,t)=>s+Number(t.amount),0),save=accountBalance('save');const summaryHtml=`<div><span>Ausgaben Lebenshaltung</span><b>${euro.format(n.spent)}</b></div><div><span>Verfügbar</span><b>${euro.format(n.available)}</b></div><div><span>Sparen aktuell</span><b>${euro.format(save)}</b></div><div><span>Einnahmen Zeitraum</span><b>${euro.format(income)}</b></div>`;q('#periodSummary').innerHTML=summaryHtml;q('#slideSummary').innerHTML=summaryHtml;renderGoals('dashboardGoals');renderGoals('slideGoals');const historyHtml=state.budgetHistory.slice(-4).reverse().map(h=>`<div class="history-row"><span>${dateLabel.format(new Date(h.start+'T12:00:00'))} – ${dateLabel.format(new Date(h.end+'T12:00:00'))}</span><span>Ausgaben ${euro.format(h.spent)}</span><b>${euro.format(h.remainder)} Rest</b></div>`).join('')||'<p class="view-intro">Nach dem nächsten Gehaltseingang erscheint hier dein erster Vergleich.</p>';q('#budgetHistory').innerHTML=historyHtml;q('#slideHistory').innerHTML=historyHtml}
function bookExpense(r,date,automatic=true){state.transactions.push({id:createId(),name:r.name,amount:Number(r.amount),date,type:'expense',account:'fixed',paymentAccount:r.paymentAccount||'main',category:r.category,note:automatic?'Automatische Fixkostenbuchung':'Fixkosten'});r.lastBookedMonth=date.slice(0,7)}
function bookIncome(r,date){state.transactions.push({id:createId(),name:r.name,amount:Number(r.amount),date,type:'income',account:r.account,category:'invest',note:'Automatische Einnahme'});r.lastBookedMonth=date.slice(0,7)}
function bookDue(){const now=new Date(),marker=monthMarker(),lastDay=new Date(now.getFullYear(),now.getMonth()+1,0).getDate();state.recurring.forEach(r=>{const day=Math.min(Number(r.day),lastDay);if(now.getDate()>=day&&r.lastBookedMonth!==marker)bookExpense(r,`${marker}-${String(day).padStart(2,'0')}`)});state.recurringIncome.forEach(r=>{const day=Math.min(Number(r.day),lastDay);if(now.getDate()>=day&&r.lastBookedMonth!==marker)bookIncome(r,`${marker}-${String(day).padStart(2,'0')}`)})}
function render(){bookDue();options();renderHeader();renderDailyBudget();renderWarnings();renderBackupReminder();renderAccounts();renderTransactions();renderChart();renderTagChart();renderTrendChart();renderRecurring();renderCategories();renderSettings();renderReminderSettings();renderShortcuts();renderShortcutButtons();renderSummary();save()}
function openExpense(shortcut){editingTransactionId=null;q('#transactionForm').reset();renderTagPicker();q('#transactionDialogEyebrow').textContent='Neue Buchung';q('#transactionDialogTitle').textContent='Ausgabe hinzufügen';q('#saveTransaction').textContent='✓';q('#deleteTransactionInDialog').hidden=true;q('#transactionForm [name=date]').value=today();q('#transactionAccount').value=shortcut?.account||'living';q('#transactionPaymentAccount').value='main';if(shortcut){q('#transactionForm [name=name]').value=shortcut.name;q('#transactionCategory').value=shortcut.category}q('#transactionDialog').showModal();requestAnimationFrame(()=>q('#transactionAmount').focus())}
function openTransactionEditor(transaction){editingTransactionId=transaction.id;q('#transactionForm').reset();q('#transactionDialogEyebrow').textContent='Buchung ändern';q('#transactionDialogTitle').textContent='Ausgabe bearbeiten';q('#saveTransaction').textContent='✓';q('#deleteTransactionInDialog').hidden=false;for(const field of ['name','date','account','paymentAccount','category','note'])q(`#transactionForm [name=${field}]`).value=transaction[field]||'';q('#transactionAmount').value=displayAmountInput(transaction.amount);q('#transactionTags').value=(transaction.tags||[]).join(', ');renderTagPicker();q('#transactionDialog').showModal();requestAnimationFrame(()=>q('#transactionAmount').focus())}
function startCycle(date){if(!state.budgetCycleInitialized){state.budgetCycleStart=date;state.budgetCycleInitialized=true;state.dailyCarryover=0;return null}const days=cycleDays(date)-1,remainder=days*(Number(state.dailyBudget)||30)+Number(state.dailyCarryover)-cycleSpent(date),end=new Date(new Date(date+'T12:00:00')-86400000).toISOString().slice(0,10);state.budgetHistory.push({start:state.budgetCycleStart,end,spent:cycleSpent(date),remainder});if(remainder<=0){state.dailyCarryover=0;state.budgetCycleStart=date;return null}return {remainder,end,date}}
function openRollover(data){const dialog=q('#monthlyBudgetDialog');q('#monthlyBudgetText').textContent=`Seit deinem letzten Gehaltseingang sind ${euro.format(data.remainder)} im Tagesbudget übrig. Was möchtest du damit machen?`;dialog.dataset.amount=data.remainder;dialog.dataset.date=data.end;dialog.dataset.newCycleDate=data.date;dialog.showModal()}
function openLeftover(){if(!pendingLeftover)return;const {amount}=pendingLeftover;q('#leftoverText').textContent=`Nach deiner festen Verteilung bleiben ${euro.format(amount)} übrig. Wohin soll der Betrag gehen?`;q('#leftoverAccountChoices').innerHTML='<legend>Zusätzlich auf dieses Konto verteilen</legend>'+state.accounts.map(a=>`<label><input required name="account" type="radio" value="${a.id}" /><span>${a.icon} ${a.name}</span></label>`).join('');q('#leftoverDialog').showModal()}
function addIncome(data){let left=Number(data.amount);state.accounts.filter(a=>a.target>0).forEach(a=>{const amount=Math.min(left,Number(a.target));if(amount){state.transactions.push({id:createId(),name:'Verteilung: '+a.name,amount,date:data.date,type:'income',account:a.id,category:a.id==='save'||a.id==='reserve'?'invest':a.id==='clothes'?'clothes':a.id==='fixed'?'rent':'groceries',note:data.note||'Aus Gehalt verteilt'});left-=amount}});return left}
function setView(id){qa('.view').forEach(x=>x.classList.toggle('active',x.id===id));qa('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===id));document.body.dataset.activeView=id;document.body.classList.toggle('view-dashboard',id==='dashboard');q('#pageTitle').textContent={dashboard:'Deine Übersicht',transactions:'Buchungen',recurring:'Fixkosten',categories:'Kategorien',settings:'Einstellungen'}[id]||'Mein Budget';renderFabActions();window.scrollTo({top:0,behavior:'smooth'})}
function openDialog(id){q('#'+id).showModal()}function closeDialog(el){el.closest('dialog').close()}
function csv(){const cols=['Datum','Name','Typ','Budgettopf','Zahlkonto','Kategorie','Tags','Betrag','Notiz'];const rows=newestFirst(state.transactions).map(t=>[t.date,t.name,t.type,account(t.account).name,paymentAccount(t.paymentAccount).name,category(t.category).name,(t.tags||[]).join(', '),t.amount,t.note||'']);return [cols,...rows].map(row=>row.map(x=>`"${String(x).replaceAll('"','""')}"`).join(';')).join('\n')}
function download(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
function exportBackup(){state.lastBackupDate=today();save();download('mein-budget-backup.json',JSON.stringify(state,null,2),'application/json');render();toast('Backup wurde gespeichert')}
let latestAvailableVersion='';async function checkForUpdate(){q('#appVersion').textContent='Version '+APP_VERSION;try{const r=await fetch('./version.json?check='+Date.now(),{cache:'no-store',headers:{'Cache-Control':'no-cache'}}),latest=await r.json();latestAvailableVersion=latest.version;const notice=q('#updateNotice');if(latest.version===APP_VERSION||sessionStorage.getItem('mein-budget-applied-version')===latest.version){notice.hidden=true;return}q('#updateVersionText').textContent=`Version ${latest.version} ist bereit.`;notice.hidden=false}catch{}}
function isInstalled(){return window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone===true}
function showInstallNotice(){if(isInstalled()||localStorage.getItem('mein-budget-install-notice-dismissed'))return;q('#installNotice').hidden=false}
function closeInstallNotice(){q('#installNotice').hidden=true;localStorage.setItem('mein-budget-install-notice-dismissed','true')}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;showInstallNotice()});window.addEventListener('appinstalled',()=>{q('#installNotice').hidden=true;localStorage.removeItem('mein-budget-install-notice-dismissed');localStorage.setItem('mein-budget-installed','true');installEvent=null});
async function runUpdate(){const button=q('#runUpdate');button.textContent='Aktualisiere …';button.disabled=true;q('#updateNotice').hidden=true;try{const registration=await navigator.serviceWorker?.getRegistration?.();await registration?.update?.();registration?.waiting?.postMessage({type:'SKIP_WAITING'});const keys=await caches.keys();await Promise.all(keys.filter(key=>key.startsWith('mein-budget-')).map(key=>caches.delete(key)));sessionStorage.setItem('mein-budget-applied-version',latestAvailableVersion);location.replace('./?updated='+Date.now())}catch{location.reload()}}
qa('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));qa('[data-close]').forEach(b=>b.onclick=()=>closeDialog(b));
const settingsInfo=[['Verteilungsregeln','Lege fest, wie ein neuer Gehaltseingang auf deine Budgettöpfe verteilt wird. Die Beträge werden der Reihe nach zugeordnet.'],['Budgettöpfe verwalten','Hier verwaltest du deine geplanten Geldbereiche wie Sparen, Lebenshaltung oder Reserve. Jeder Topf kann ein eigenes Ziel, Symbol und eine Farbe haben.'],['Zahlkonten verwalten','Zahlkonten zeigen, von welchem echten Konto eine Ausgabe bezahlt wurde – zum Beispiel Girokonto, Kreditkarte oder Bargeld.'],['Ziele verwalten','Lege konkrete Sparziele an und behalte im Blick, wie viel du davon bereits erreicht hast.'],['Shortcuts verwalten','Shortcuts sind deine Schnellwahlen für häufige Ausgaben. Sie füllen beim Hinzufügen automatisch Name, Kategorie und Budgettopf vor.'],['Datensicherung','Speichere regelmäßig ein Backup deiner Daten. Über „Backup laden“ kannst du es später auf diesem oder einem anderen Gerät wieder einspielen.']];qa('#settings details.panel').forEach((panel,index)=>{const info=settingsInfo[index],summary=panel.querySelector('summary');if(!info||!summary)return;const button=document.createElement('button');button.type='button';button.className='settings-info-button';button.textContent='i';button.setAttribute('aria-label',info[0]+' erklären');button.onclick=e=>{e.preventDefault();e.stopPropagation();q('#settingsInfoTitle').textContent=info[0];q('#settingsInfoText').textContent=info[1];q('#settingsInfoDialog').showModal()};summary.append(button)});
const tutorialSteps=[{symbol:'✦',title:'Willkommen bei Mein Budget',text:'In wenigen Schritten richtest du dein Haushaltsbuch ein. Deine Daten bleiben dabei auf deinem Gerät.',button:'Einrichtung starten'},{symbol:'↗',title:'Erstes Gehalt eintragen',text:'Trage deinen nächsten Geldeingang ein. Die App verteilt ihn anschließend nach deinen Regeln auf deine Budgettöpfe.',button:'Gehalt speichern'},{symbol:'◌',title:'Restbetrag zuordnen',text:'Dein Gehalt ist höher als deine festen Verteilungsregeln. Wohin soll der übrige Betrag gehen?',button:'Restbetrag zuordnen'},{symbol:'☀',title:'Tagesbudget festlegen',text:'Aus deinem Lebenshaltungs-Topf ergibt sich ein fairer Tageswert. Du kannst die Empfehlung übernehmen oder deinen eigenen Betrag eintragen.',button:'Tagesbudget speichern'},{symbol:'↻',title:'Erste Fixkosten anlegen',text:'Lege eine wiederkehrende Ausgabe wie Miete, Telefon oder ein Abo an. Sie wird künftig automatisch zum Fälligkeitstag gebucht.',button:'Fixkosten speichern'},{symbol:'⚡',title:'Schnellwahl einrichten',text:'Erstelle einen Shortcut für häufige Ausgaben. So sind Einkäufe später mit wenigen Klicks erfasst.',button:'Shortcut speichern'},{symbol:'✓',title:'Du bist startklar',text:'Auf der Übersicht siehst du deine Töpfe, das Tagesbudget und die letzten Bewegungen. Über das Plus kannst du jederzeit etwas hinzufügen.',button:'Zum Dashboard'}];let tutorialLeftover=null,tutorialRecommendedDaily=null;
function tutorialFields(step){if(step===1)return `<label>Betrag <input required name="amount" type="number" min="0.01" step="0.01" inputmode="decimal" placeholder="z. B. 2.530,00" /></label><label>Datum <input required name="date" type="date" value="${today()}" /></label>`;if(step===2)return `<fieldset class="tutorial-account-choice"><legend>Restbetrag verteilen auf</legend>${state.accounts.map(a=>`<label><input required name="account" type="radio" value="${a.id}" /><span>${a.icon} ${a.name}</span></label>`).join('')}</fieldset>`;if(step===3){const recommended=Math.max(1,Math.round((tutorialRecommendedDaily||Number(account('living').target)/31)*100)/100);return `<p class="tutorial-recommendation">Empfehlung aus Lebenshaltung: <b>${euro.format(recommended)} pro Tag</b><small>(${euro.format(recommended*31)} ÷ 31 Tage)</small></p><label>Dein Tagesbudget <input required name="dailyBudget" type="number" min="1" step="0.01" value="${recommended}" /></label>`}if(step===4)return `<label>Name <input required name="name" type="text" placeholder="z. B. Miete" /></label><div class="form-row"><label>Betrag <input required name="amount" type="number" min="0.01" step="0.01" /></label><label>Fälligkeitstag <input required name="day" type="number" min="1" max="31" value="1" /></label></div><label>Kategorie <select required name="category">${state.categories.map(c=>`<option value="${c.id}">${c.icon} ${c.name}</option>`).join('')}</select></label>`;if(step===5)return `<label>Name <input required name="name" type="text" placeholder="z. B. Apotheke" /></label><label>Kategorie <select required name="category">${state.categories.map(c=>`<option value="${c.id}">${c.icon} ${c.name}</option>`).join('')}</select></label>`;return ''}
function openTutorial(step=0){const current=tutorialSteps[step]||tutorialSteps[0];state.tutorialActive=true;state.tutorialStep=step;q('#tutorialStepLabel').textContent=`Erste Schritte · ${step+1} von ${tutorialSteps.length}`;q('#tutorialSymbol').textContent=current.symbol;q('#tutorialTitle').textContent=current.title;q('#tutorialText').textContent=current.text;q('#tutorialFields').innerHTML=tutorialFields(step);q('#tutorialDots').innerHTML=tutorialSteps.map((_,index)=>`<span class="${index===step?'active':''}"></span>`).join('');q('#tutorialPrimary').textContent=current.button;q('#tutorialSecondary').hidden=step===0||step===tutorialSteps.length-1;if(!q('#tutorialDialog').open)q('#tutorialDialog').showModal();save()}
function completeTutorial(){state.tutorialActive=false;state.tutorialCompleted=true;tutorialLeftover=null;save();q('#tutorialDialog').close();setView('dashboard')}
q('#tutorialForm').onsubmit=e=>{e.preventDefault();const step=state.tutorialStep||0,data=Object.fromEntries(new FormData(e.target));if(step===0){openTutorial(1);return}if(step===1){const before=state.transactions.length;startCycle(data.date);const left=addIncome(data);tutorialRecommendedDaily=(Number(state.transactions.slice(before).find(t=>t.account==='living')?.amount)||Number(account('living').target))/31;render();if(left>0){tutorialLeftover={amount:left,date:data.date};openTutorial(2)}else openTutorial(3);return}if(step===2&&tutorialLeftover){state.transactions.push({id:createId(),name:'Restbetrag aus Gehalt',amount:tutorialLeftover.amount,date:tutorialLeftover.date,type:'income',account:data.account,category:data.account==='save'?'invest':'groceries',note:'Zusätzliche Verteilung'});tutorialLeftover=null;render();openTutorial(3);return}if(step===3){state.dailyBudget=Number(data.dailyBudget)||30;render();openTutorial(4);return}if(step===4){state.recurring.push({id:createId(),name:data.name,amount:Number(data.amount),day:Number(data.day),paymentAccount:'main',category:data.category});render();openTutorial(5);return}if(step===5){const categoryValue=category(data.category);state.shortcuts.push({id:createId(),name:data.name,icon:categoryValue.icon,account:'living',category:data.category});render();openTutorial(6);return}if(step===6)completeTutorial()};q('#tutorialSecondary').onclick=()=>{const step=state.tutorialStep||0;if(step===1)openTutorial(3);else if(step===2){tutorialLeftover=null;openTutorial(3)}else if(step===3)openTutorial(4);else if(step===4)openTutorial(5);else if(step===5)openTutorial(6)};q('#skipTutorial').onclick=completeTutorial;const restartTutorial=document.createElement('button');restartTutorial.type='button';restartTutorial.id='restartTutorial';restartTutorial.className='secondary-button';restartTutorial.textContent='Einführung starten';q('#settings .backup-actions').append(restartTutorial);restartTutorial.onclick=()=>openTutorial(0);
function openTutorialInvite(){q('#tutorialInviteDialog').showModal()}q('#startTutorialInvite').onclick=()=>{state.tutorialInviteEligible=false;save();q('#tutorialInviteDialog').close();openTutorial(0)};q('#declineTutorialInvite').onclick=()=>{state.tutorialInviteDismissed=true;save();q('#tutorialInviteDialog').close();toast('Die Einführung findest du unter Mehr → Hilfe & Einführung.')};const helpPanel=document.createElement('details');helpPanel.className='panel help-panel';helpPanel.innerHTML='<summary class="panel-head"><div><p class="eyebrow">Unterstützung</p><h2>Hilfe & Einführung</h2></div></summary><p class="view-intro">Starte die Einführung erneut oder finde hier künftig weitere Hilfen zur App.</p><div class="help-actions"></div>';q('#settings .settings-grid').append(helpPanel);restartTutorial.remove();helpPanel.querySelector('.help-actions').append(restartTutorial);
