async function deliverDailyReminder(test=false){const data=dailyReminder();if(!test&&(!data.enabled||data.lastSent===today()||todayHasExpense()))return false;const allowed=await requestReminderPermission();if(!allowed){toast('Bitte erlaube Benachrichtigungen in den Browser-Einstellungen.');return false}const title='Mein Budget',options={body:data.message,tag:'mein-budget-daily-reminder',renotify:test};try{const registration=await navigator.serviceWorker?.getRegistration?.();if(registration?.active&&typeof registration.showNotification==='function')await registration.showNotification(title,options);else if(typeof Notification==='function')new Notification(title,options);else throw Error('notification-unavailable');if(!test){data.lastSent=today();save()}toast(test?'Testbenachrichtigung wurde ausgelöst.':'Tägliche Erinnerung wurde ausgelöst.');return true}catch{toast('Test konnte nicht angezeigt werden. Öffne die installierte App und prüfe die Benachrichtigungsfreigabe.');return false}}
