let dashScrollTimer;
dashTrack.addEventListener('scroll',()=>{clearTimeout(dashScrollTimer);dashScrollTimer=setTimeout(updateDashDots,60)},{passive:true});
dashDotEls.forEach((d,i)=>d.onclick=()=>dashTrack.scrollTo({left:i*dashTrack.clientWidth,behavior:'smooth'}));
addEventListener('resize',updateDashDots);
updateDashDots();

// Backup-Erinnerung: das Ausrufezeichen oben rechts im Dashboard-Kopf
// öffnet die Backup-Option als Popover, statt dauerhaft Platz zu belegen.
const heroAlert=q('#heroAlert'),backupPanel=q('#backupReminder');
function closeBackupReminder(){backupPanel.hidden=true;heroAlert.setAttribute('aria-expanded','false')}
function openBackupReminder(){const r=heroAlert.getBoundingClientRect();
// clientWidth statt innerWidth: innerWidth zählt die Scrollbar mit, getBoundingClientRect nicht.
backupPanel.style.top=Math.round(r.bottom+8)+'px';backupPanel.style.right=Math.round(document.documentElement.clientWidth-r.right)+'px';backupPanel.hidden=false;heroAlert.setAttribute('aria-expanded','true')}
heroAlert.onclick=()=>{if(backupPanel.hidden)openBackupReminder();else closeBackupReminder()};
document.addEventListener('click',e=>{if(!backupPanel.hidden&&!backupPanel.contains(e.target)&&e.target!==heroAlert)closeBackupReminder()});
addEventListener('keydown',e=>{if(e.key==='Escape'&&!backupPanel.hidden)closeBackupReminder()});
addEventListener('resize',()=>{if(!backupPanel.hidden)openBackupReminder()});

document.addEventListener('click',e=>{if(e.target.id==='quickBackup'){exportBackup();return}if('loadBackup' in e.target.dataset){q('#importBackup').click();return}const dashboard=e.target.closest('[data-dashboard-shortcut]'),shortcut=e.target.closest('[data-shortcut]');if(dashboard||shortcut){openExpense(state.shortcuts.find(x=>x.id===(dashboard?.dataset.dashboardShortcut||shortcut?.dataset.shortcut)));return}const data=e.target.dataset;if(data.openEditTransaction){openTransactionEditor(state.transactions.find(x=>x.id===data.openEditTransaction));return}if(data.deleteTransaction){state.transactions=state.transactions.filter(x=>x.id!==data.deleteTransaction);render();toast('Buchung gelöscht')}else if(data.receipt){const t=state.transactions.find(x=>x.id===data.receipt);q('#receiptPreview').src=t.receipt;openDialog('receiptDialog')}else if(data.bookRecurring){const r=state.recurring.find(x=>x.id===data.bookRecurring);bookExpense(r,today(),false);render();toast(r.name+' wurde gebucht')}else if(data.deleteRecurring){state.recurring=state.recurring.filter(x=>x.id!==data.deleteRecurring);render()}else if(data.editRecurring){const r=state.recurring.find(x=>x.id===data.editRecurring);editingRecurringId=r.id;q('#recurringForm [name=name]').value=r.name;q('#recurringForm [name=amount]').value=r.amount;q('#recurringForm [name=day]').value=r.day;q('#recurringCategory').value=r.category;openDialog('recurringDialog')}else if(data.deleteRecurringIncome){state.recurringIncome=state.recurringIncome.filter(x=>x.id!==data.deleteRecurringIncome);render()}else if(data.editRecurringIncome){const r=state.recurringIncome.find(x=>x.id===data.editRecurringIncome);editingRecurringIncomeId=r.id;q('#recurringIncomeForm [name=name]').value=r.name;q('#recurringIncomeForm [name=amount]').value=r.amount;q('#recurringIncomeForm [name=day]').value=r.day;q('#recurringIncomeAccount').value=r.account;openDialog('recurringIncomeDialog')}else if(data.deleteShortcut){state.shortcuts=state.shortcuts.filter(x=>x.id!==data.deleteShortcut);render()}else if(data.editShortcut){const s=state.shortcuts.find(x=>x.id===data.editShortcut);editingShortcutId=s.id;q('#shortcutForm [name=name]').value=s.name;q('#shortcutForm [name=icon]').value=s.icon;q('#shortcutAccount').value=s.account;q('#shortcutCategory').value=s.category;openDialog('shortcutDialog')}else if(data.deleteAccount){state.accounts=state.accounts.filter(x=>x.id!==data.deleteAccount);render()}else if(data.editAccount){const a=account(data.editAccount);editingAccountId=a.id;q('#accountForm [name=name]').value=a.name;q('#accountForm [name=icon]').value=a.icon;q('#accountForm [name=color]').value=a.color;q('#accountForm [name=target]').value=a.target;openDialog('accountDialog')}else if(data.deleteGoal){state.goals=state.goals.filter(x=>x.id!==data.deleteGoal);render()}else if(data.editGoal){const g=state.goals.find(x=>x.id===data.editGoal);editingGoalId=g.id;q('#goalForm [name=name]').value=g.name;q('#goalForm [name=target]').value=g.target;q('#goalForm [name=current]').value=g.current;q('#goalForm [name=icon]').value=g.icon;openDialog('goalDialog')}else if(data.deleteCategory){state.categories=state.categories.filter(x=>x.id!==data.deleteCategory);render()}else if(data.editCategory){const c=category(data.editCategory),name=prompt('Kategoriename ändern:',c.name);if(name?.trim()){c.name=name.trim();render();toast('Kategorie geändert')}}else if(data.rollover){const dialog=q('#monthlyBudgetDialog'),amount=Number(dialog.dataset.amount),date=dialog.dataset.date;if(data.rollover==='carry')state.dailyCarryover=amount;else{const target=data.rollover==='save'?'save':'reserve';if(target==='reserve'&&!state.accounts.some(a=>a.id==='reserve'))state.accounts.push({id:'reserve',name:'Reserve',icon:'◫',color:'#149876',target:0});state.transactions.push({id:createId(),name:'Monatsrest',amount,date,type:'expense',account:'living',category:'invest',note:'Monatsabschluss'});state.transactions.push({id:createId(),name:'Monatsrest',amount,date,type:'income',account:target,category:'invest',note:'Monatsabschluss'});state.dailyCarryover=0}state.budgetCycleStart=dialog.dataset.newCycleDate;dialog.close();render();if(pendingLeftover)setTimeout(openLeftover,0)}});
document.addEventListener('click',e=>{const data=e.target.dataset;if(data.editRecurring){const r=state.recurring.find(x=>x.id===data.editRecurring);q('#recurringPaymentAccount').value=r.paymentAccount||'main';q('#recurringForm [name=initialBooking]').value='due'}else if(data.editPaymentAccount){const a=paymentAccount(data.editPaymentAccount);editingPaymentAccountId=a.id;q('#paymentAccountForm [name=name]').value=a.name;q('#paymentAccountForm [name=icon]').value=a.icon;openDialog('paymentAccountDialog')}else if(data.deletePaymentAccount){state.paymentAccounts=state.paymentAccounts.filter(x=>x.id!==data.deletePaymentAccount);state.transactions.forEach(t=>{if(t.paymentAccount===data.deletePaymentAccount)t.paymentAccount='main'});state.recurring.forEach(r=>{if(r.paymentAccount===data.deletePaymentAccount)r.paymentAccount='main'});render();toast('Zahlkonto gelöscht')}});
document.body.dataset.activeView='dashboard';if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(registration=>registration.update()).catch(()=>{});render();checkForUpdate();document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkForUpdate()});if(!isInstalled())showInstallNotice();if(state.tutorialInviteEligible&&!state.tutorialInviteDismissed&&!state.tutorialCompleted)setTimeout(openTutorialInvite,450);
